package pzvrphysicality;
import java.util.*;import local.pzvr.ControllerProfiles;import local.pzvr.XrBackend;
/** Production sidecar lifecycle through authored action/state transport only. */
public final class ControllerTouchTest {
 private static int checks;private static void check(boolean value,String why){if(!value)throw new AssertionError(why);checks++;}
 private static ControllerTouchFixture fixture;private static ControllerTouch.Context context;private static Object backend,session,set,lock;
 private static void reset(){fixture=new ControllerTouchFixture();ControllerTouch.transportForTest(fixture);backend=new Object();session=new Object();set=new Object();lock=new Object();context=ControllerTouchFixture.context(backend,session,set,lock,true);}
 private static void capture(XrBackend.Hand[] hands,long now){synchronized(lock){ControllerTouch.capture(context,null,12345,hands,now);}}
 public static void main(String[] args)throws Exception {
  check(ControllerTouch.allowsInput(local.pzvr.PresenceFixture.presence(true)),"package-private presence method reads allowed state");check(!ControllerTouch.allowsInput(local.pzvr.PresenceFixture.presence(false)),"package-private presence method reads blocked state");check(!ControllerTouch.allowsInput(null),"absent presence denied");
  reset();var profile=ControllerTouchFixture.profile();var originals=profile.bindings();check(ControllerTouch.suggest(context,profile,null),"successful union skips original suggest");check(fixture.creates==7,"one passive action per channel");check(fixture.suggestions==1&&fixture.union.size()==16,"original plus all classic touch bindings");check(profile.bindings()==originals&&originals.size()==2,"original profile list unchanged");
  check(fixture.union.get(0).action()==context.originals.get("native_trigger")&&fixture.union.get(0).path().equals(originals.get(0).path()),"first native binding preserved");check(fixture.union.get(1).action()==context.originals.get("native_grip")&&fixture.union.get(1).path().equals(originals.get(1).path()),"second native binding preserved");
  for(var channel:ControllerTouch.Channel.values())for(int side=0;side<2;side++)check(fixture.union.contains(new ControllerTouch.Bound(channel,channel.path(side))),"exact supported path "+channel+"/"+side);
  check(fixture.union.stream().noneMatch(b->b.path().contains("squeeze/touch")||b.path().contains("proximity")||b.path().contains("force")),"no invented squeeze contact or proximity");
  check(ControllerTouch.suggest(context,profile,null)&&fixture.creates==7,"repeat suggestion reuses actions");check(context.set==set&&context.session==session&&context.originals.size()==2,"same original set and session retained");
  var l=ControllerTouchFixture.hand(true);var r=ControllerTouchFixture.hand(true);long now=1_000_000_000L;var frame=ControllerTouchFixture.frame(now+1,l,r);
  fixture.supported(0);fixture.supported(1);fixture.contact(ControllerTouch.Channel.TRIGGER_TOUCH,0,true);fixture.contact(ControllerTouch.Channel.STICK_TOUCH,1,true);fixture.value(ControllerTouch.Channel.TRIGGER_VALUE,0,.3f);fixture.value(ControllerTouch.Channel.SQUEEZE_VALUE,0,.8f);
  capture(new XrBackend.Hand[]{l,r},now);check(ControllerTouch.input(frame,0,now+10)==ControllerTouch.Input.UNKNOWN&&fixture.contacts==0,"suggestion alone cannot fabricate native attachment");check(ControllerTouch.status().contains("registered=1 attached=0"),"registration and attachment reported separately");
  ControllerTouch.actionsCreated(context,true);check(ControllerTouch.status().contains("registered=1 attached=1"),"successful original action creation publishes attachment receipt");capture(new XrBackend.Hand[]{l,r},now);
  var left=ControllerTouch.input(frame,0,now+10);var right=ControllerTouch.input(frame,1,now+10);check(left.trigger().available()&&left.trigger().touched(),"left trigger contact retained");check(!left.stick().touched()&&right.stick().touched(),"right stick touch remains separate");check(left.triggerValue().value()==.3f&&left.squeeze().value()==.8f,"separate analog channels");check(fixture.contacts==10&&fixture.values==4,"reads each side and channel after existing sync");
  var reading=ControllerTouch.reading(frame,0,now+10);check(reading.hostTime()==now&&reading.generation()>0&&reading.input()==left,"reading exposes exact raw sample time and generation");
  String diagnostic=ControllerTouch.diagnostics(frame,now+10);check(diagnostic.contains("L[trigger=touch stick=clear rest=clear X=clear Y=clear triggerValue=0.30 squeeze=0.80]"),"left diagnostic shows unfiltered separate sensor values");check(diagnostic.contains("R[trigger=clear stick=touch rest=clear A=clear B=clear"),"right diagnostic names physical face buttons");check(ControllerTouch.diagnostics(frame,now+ControllerTouch.MAX_AGE+1).contains("triggerValue=? squeeze=?"),"stale diagnostics show unavailable instead of contact released");
  check(ControllerTouch.input(frame,0,now+ControllerTouch.MAX_AGE+1)==ControllerTouch.Input.UNKNOWN,"stale host sample rejected");check(ControllerTouch.input(frame,0,now-1)==ControllerTouch.Input.UNKNOWN,"host rollback rejected");check(ControllerTouch.input(frame,-1,now+10)==ControllerTouch.Input.UNKNOWN,"invalid side rejected");
  check(ControllerTouch.input(new XrBackend.Frame(now+1,true,false,null,List.of(),l,r),0,now+10)==ControllerTouch.Input.UNKNOWN,"unfocused frame rejected");check(ControllerTouch.input(ControllerTouchFixture.frame(now-1,l,r),0,now+10)==ControllerTouch.Input.UNKNOWN,"frame predating sample rejected");check(ControllerTouch.input(ControllerTouchFixture.frame(now+100,l,r),0,now+10)==ControllerTouch.Input.UNKNOWN,"future frame rejected");
  var equal=ControllerTouchFixture.hand(true);check(equal.equals(l)&&equal!=l,"authored equal record uses different identity");check(ControllerTouch.input(ControllerTouchFixture.frame(now+1,equal,r),0,now+10)==ControllerTouch.Input.UNKNOWN,"equal-valued hand cannot borrow input");
  var renderL=ControllerTouchFixture.hand(true);var renderR=ControllerTouchFixture.hand(true);capture(new XrBackend.Hand[]{renderL,renderR},now+2);check(ControllerTouch.input(frame,0,now+10).trigger().touched(),"render sampling does not replace exact earlier input hands");
  fixture.touch.remove(ControllerTouch.Channel.REST_TOUCH+"/0");capture(new XrBackend.Hand[]{l,r},now+3);var unavailable=ControllerTouch.input(ControllerTouchFixture.frame(now+4,l,r),0,now+10);check(!unavailable.rest().available()&&!unavailable.rest().touched(),"inactive channel unknown, never false contact");
  fixture.rightProfile=999;capture(new XrBackend.Hand[]{l,r},now+5);var changed=ControllerTouchFixture.frame(now+6,l,r);check(ControllerTouch.input(changed,1,now+10)==ControllerTouch.Input.UNKNOWN,"unsupported active right profile unavailable");check(ControllerTouch.input(frame,0,now+10)==ControllerTouch.Input.UNKNOWN,"profile change retires old samples");check(ControllerTouch.input(changed,0,now+10).trigger().available(),"unaffected physical left profile still available");
  check(ControllerTouch.reading(changed,0,now+10).generation()!=reading.generation(),"profile change resets avatar filter provenance");
  context=ControllerTouchFixture.context(backend,session,set,lock,false);capture(new XrBackend.Hand[]{l,r},now+7);check(ControllerTouch.input(changed,0,now+10)==ControllerTouch.Input.UNKNOWN,"lost focus/session eligibility clears prior data");
  check(ControllerTouch.status().contains("session input ineligible"),"passive registration is distinguished from current sampling eligibility");
  context=ControllerTouchFixture.context(backend,session,set,lock,true);ControllerTouch.capture(context,null,12345,new XrBackend.Hand[]{l,r},now+8);check(ControllerTouch.input(ControllerTouchFixture.frame(now+9,l,r),0,now+10)==ControllerTouch.Input.UNKNOWN,"read without upstream lock rejected");
  capture(new XrBackend.Hand[]{ControllerTouchFixture.hand(false),r},now+9);check(!ControllerTouch.input(ControllerTouchFixture.frame(now+10,ControllerTouchFixture.hand(false),r),0,now+11).trigger().available(),"untracked input unavailable");
  capture(new XrBackend.Hand[]{l,r},now+10);ControllerTouch.close(backend);check(ControllerTouch.input(ControllerTouchFixture.frame(now+11,l,r),0,now+12)==ControllerTouch.Input.UNKNOWN,"close removes retained samples");check(fixture.creates==7,"close does not duplicate native destruction");
  reset();fixture.result=-1;int originalCalls=0;if(!ControllerTouch.suggest(context,profile,null))originalCalls++;check(originalCalls==1,"rejected union executes original fallback");check(profile.bindings()==originals,"rejection leaves original profile unchanged");check(!ControllerTouch.suggest(context,profile,null)&&fixture.suggestions==1,"failed registration cannot retry after attach");
  reset();fixture.failCreate=true;check(!ControllerTouch.suggest(context,profile,null)&&fixture.suggestions==0,"partial creation failure never submits incomplete union");
  reset();check(!ControllerTouch.suggest(context,new ControllerProfiles.Profile("/interaction_profiles/meta/touch_controller_plus","Plus","",originals),null)&&fixture.creates==0,"unadmitted Meta profile ignored");check(!ControllerTouch.suggest(context,new ControllerProfiles.Profile(ControllerTouch.PROFILE,"Touch","required_extension",originals),null)&&fixture.creates==0,"unexpected extension ignored");
  check(!ControllerTouch.suggest(new Object(),profile,null)&&fixture.creates==0,"production rejects unknown backend SDK owner");
  reset();check(ControllerTouch.suggest(context,profile,null),"fresh registration");ControllerTouch.actionsCreated(context,true);fixture.supported(0);fixture.supported(1);fixture.failQuery=true;capture(new XrBackend.Hand[]{l,r},now);check(ControllerTouch.input(frame,0,now+10)==ControllerTouch.Input.UNKNOWN,"query error retains native fallback");
  fixture.failQuery=false;capture(new XrBackend.Hand[]{l,r},now);var replaced=ControllerTouchFixture.context(backend,new Object(),new Object(),lock,true);synchronized(lock){ControllerTouch.capture(replaced,null,123,new XrBackend.Hand[]{l,r},now+1);}check(ControllerTouch.input(frame,0,now+10)==ControllerTouch.Input.UNKNOWN,"new session cannot borrow old generation");
  check(ControllerTouch.status().contains("action set/session changed"),"touch rejection reports exact lifecycle identity mismatch");
  reset();FingerPoseDriver.configureForTest(false);check(ControllerTouch.suggest(context,profile,null),"menu startup registers passive channels while finger visuals Off");ControllerTouch.actionsCreated(context,true);fixture.supported(0);fixture.supported(1);fixture.value(ControllerTouch.Channel.TRIGGER_VALUE,0,.41f);capture(new XrBackend.Hand[]{l,r},now);check(ControllerTouch.input(frame,0,now+10).triggerValue().value()==.41f&&!FingerPoseDriver.enabled(),"existing menu session samples passive pressure with visual mode Off");
  int creates=fixture.creates,suggestions=fixture.suggestions;FingerPoseDriver.configureForTest(true);check(FingerPoseDriver.enabled()&&ControllerTouch.input(frame,0,now+10).triggerValue().value()==.41f,"later world-start enable uses already attached passive input");FingerPoseDriver.configureForTest(false);FingerPoseDriver.configureForTest(true);check(fixture.creates==creates&&fixture.suggestions==suggestions&&ControllerTouch.status().contains("attached=1"),"in-game Off/On changes no action creation, suggestion or native attachment");
  check(!ControllerTouch.suggest(context,profile,null)&&fixture.creates==creates&&fixture.suggestions==suggestions,"post-attachment passive registration never mutates native lifecycle");
  reset();ControllerTouch.actionsCreated(context,true);check(!ControllerTouch.status().contains("registered=1"),"missing startup hook cannot be repaired by inventing registration after attachment");check(!ControllerTouch.suggest(context,profile,null)&&fixture.creates==0,"observed existing native attachment prevents late action creation");capture(new XrBackend.Hand[]{l,r},now);check(ControllerTouch.input(frame,0,now+10)==ControllerTouch.Input.UNKNOWN,"late-loaded sidecar explicitly remains unavailable");
  reset();check(ControllerTouch.suggest(context,profile,null),"failure case registers first");ControllerTouch.actionsCreated(context,false);fixture.supported(0);fixture.supported(1);capture(new XrBackend.Hand[]{l,r},now);check(ControllerTouch.input(frame,0,now+10)==ControllerTouch.Input.UNKNOWN&&fixture.contacts==0,"failed original attachment cannot publish sensor samples");check(!ControllerTouch.suggest(context,profile,null),"failed attachment prohibits late retry");
  reset();var noSession=ControllerTouchFixture.context(backend,null,set,lock,true);check(!ControllerTouch.suggest(noSession,profile,null)&&fixture.creates==0,"registration cannot retain null session identity");
  check(ControllerTouch.suggest(context,profile,null),"subaction-path consistency case registers");ControllerTouch.actionsCreated(context,true);fixture.supported(0);fixture.supported(1);for(var channel:ControllerTouch.Channel.values())check(Arrays.equals(fixture.declared.get(channel),new long[]{11,12}),"every owned shared action declares both exact hand paths "+channel);
  var wrongPaths=new ControllerTouch.Context(backend,context.instance,session,set,lock,new long[]{12,11},context.originals,true);synchronized(lock){ControllerTouch.capture(wrongPaths,null,12345,new XrBackend.Hand[]{l,r},now);}check(fixture.contacts==0&&ControllerTouch.input(frame,0,now+10)==ControllerTouch.Input.UNKNOWN,"same set/session cannot query reversed undeclared paths");check(ControllerTouch.status().contains("declared subaction paths changed"),"subaction mismatch has explicit diagnostic");capture(new XrBackend.Hand[]{l,r},now);check(fixture.contacts==10&&fixture.values==4,"original declared paths resume separate boolean and float queries");
  reset();var duplicates=new ControllerTouch.Context(backend,context.instance,session,set,lock,new long[]{11,11},context.originals,true);check(!ControllerTouch.suggest(duplicates,profile,null)&&fixture.creates==0,"duplicate physical hand paths rejected before action creation");FingerPoseDriver.configureForTest(false);
  System.out.println("Controller touch lifecycle: "+checks+" checks passed; authored transport, no XR session or API execution");
 }
}
